import { type Product } from '../lib/api';

function formatPrice(price: number): string {
  return 'Rp ' + price.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

interface ProductCardProps {
  product: Product;
}

export default function ProductCard({ product }: ProductCardProps) {
  const primaryImage = product.images?.find(i => i.is_primary) || product.images?.[0];
  const cond = product.condition;

  const stockStatus = product.stock === 0
    ? 'Habis'
    : product.stock <= 3
    ? `Stok Terbatas (${product.stock})`
    : 'Stok Tersedia';

  const stockDotClass = product.stock === 0
    ? 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.6)]'
    : product.stock <= 3
    ? 'bg-orange-500 shadow-[0_0_8px_rgba(249,115,22,0.6)]'
    : 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]';

  return (
    <div className="group relative bg-surface-container rounded-xl overflow-hidden glass-card transition-all duration-500 hover:-translate-y-2">
      <div className="aspect-[3/4] overflow-hidden relative">
        {primaryImage ? (
          <img
            alt={product.name}
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
            src={primaryImage.url}
          />
        ) : (
          <div className="w-full h-full bg-surface-container-low flex items-center justify-center">
            <span className="material-symbols-outlined text-5xl text-on-surface-variant/20">image</span>
          </div>
        )}
        {cond && (
          <div className="absolute top-4 right-4 bg-primary/90 text-on-primary-fixed px-2 py-1 rounded text-[10px] font-black uppercase tracking-wider">
            {cond.abbreviation}
          </div>
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-surface-container via-transparent to-transparent opacity-60"></div>
      </div>
      <div className="p-6">
        <p className="text-[10px] font-bold text-secondary uppercase tracking-widest mb-1">
          {product.collection || product.categories?.map(c => c.name).join(', ') || '—'}
        </p>
        <h3 className="text-xl font-bold mb-4 group-hover:text-primary transition-colors" style={{ color: '#E0F7FA' }}>
          {product.name}
        </h3>
        <div className="flex items-center justify-between">
          <div className="flex flex-col">
            <span className="text-xs text-on-surface-variant font-medium">Price</span>
            <span className="text-lg font-black text-[#00D4FF] font-extrabold">{formatPrice(product.price)}</span>
          </div>
          <button className="h-10 w-10 bg-surface-bright rounded-lg flex items-center justify-center text-primary hover:bg-primary hover:text-on-primary-fixed transition-all">
            <span className="material-symbols-outlined">shopping_cart</span>
          </button>
        </div>
        <div className="mt-4 pt-4 border-t border-outline-variant/10 flex items-center gap-2">
          <div className={`w-1.5 h-1.5 rounded-full ${stockDotClass}`}></div>
          <span className="text-[10px] text-on-surface-variant font-bold uppercase tracking-widest">{stockStatus}</span>
        </div>
      </div>
    </div>
  );
}
